cat > src-tauri/src/lan_review.rs <<'EOF'
//! Desktop-owned temporary disclosure of one exact message over LAN HTTP.
use crate::{
    chat_commands::NodeState, commands::CommandError, runtime_admission::RuntimeAdmission,
    state::AppState,
};
use mesh_talk_core::{discovery::LanIpv4Scope, node::FavoriteSource};
use std::{
    sync::{Arc, Mutex},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    net::TcpListener,
    sync::watch,
    time::{Instant, timeout},
};

#[derive(Clone, Default)]
pub(crate) struct LanReview(Arc<Mutex<Option<watch::Sender<bool>>>>);

impl LanReview {
    pub(crate) fn stop(&self) {
        if let Some(stop) = self.0.lock().expect("LAN review state").as_ref() {
            stop.send_replace(true);
        }
    }
}

#[derive(serde::Serialize)]
pub struct LanReviewLink {
    url: String,
}

fn invalid(detail: &str) -> CommandError {
    CommandError::Service(detail.into())
}

#[tauri::command]
pub async fn owner_preview_lan_review(
    owner: String,
    source: FavoriteSource,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<String, CommandError> {
    RuntimeAdmission::capture(&app, &node, &owner)?
        .blocking(move |runtime, _| {
            Ok(runtime.handle().inspect_lan_review_text(&source)?.0)
        })
        .await
}

#[tauri::command]
pub async fn owner_start_lan_review(
    owner: String,
    source: FavoriteSource,
    preview: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<LanReviewLink, CommandError> {
    if preview.is_empty() || preview.len() > 16 * 1024 {
        return Err(invalid("Invalid LAN review preview"));
    }
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    let revision = app.app_lock().authorization_revision()?;
    let scope = LanIpv4Scope::current()
        .ok_or_else(|| invalid("LAN review needs one active physical IPv4 interface"))?;
    let listener = TcpListener::bind((scope.address(), 0))
        .await
        .map_err(|_| invalid("Could not listen on the LAN address"))?;
    let address = listener.local_addr().map_err(|_| invalid("Missing LAN address"))?;
    let path = format!("/{}", hex::encode(rand::random::<[u8; 24]>()));
    let url = format!("http://{address}{path}");
    let state = app.lan_review.clone();
    let node = node.inner().clone();
    let mut guard = node.0.clone().write_owned().await;
    tokio::task::spawn_blocking(move || {
        let runtime = guard.as_mut().ok_or_else(CommandError::not_started)?;
        let core = runtime.handle();
        let mut content_changes = core.subscribe_ui_changes();
        let mut network_changes = core.subscribe_network_changes();
        let (stop, stopping) = watch::channel(false);
        let mut runtime_end = tokio::sync::oneshot::channel();
        let deadline = admission.checked_at_lock_revision(runtime, revision, || {
            let (text, source_expiry) = core.inspect_lan_review_text(&source)?;
            if text != preview || !scope.is_current() {
                return Err(invalid("LAN review source or interface changed"));
            }
            let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
            let duration = source_expiry
                .map_or(Duration::from_secs(900), |end| {
                    Duration::from_millis(end).saturating_sub(now).min(Duration::from_secs(900))
                });
            if duration.is_zero() {
                return Err(invalid("LAN review source expired"));
            }
            let mut active = state.0.lock().expect("LAN review state");
            if active.is_some() {
                return Err(invalid("Stop the existing LAN review first"));
            }
            *active = Some(stop.clone());
            Ok(Instant::now() + duration)
        })?;
        let admission = Arc::new(admission);
        let task = tokio::spawn(async move {
            let grant = Arc::new(Grant { admission, node, source, preview, scope, path, revision, deadline, stopping });
            let authorization = grant.clone();
            let server = crate::lan_review_http::serve(listener, grant.stopping.clone(), move |peer, path| {
                let grant = authorization.clone();
                async move {
                    if path != grant.path || !grant.scope.admits(peer) {
                        return None;
                    }
                    grant.read().await
                }
            });
            tokio::pin!(server);
            let invalidation = async {
                loop {
                    tokio::select! {
                        _ = &mut runtime_end.1 => break,
                        _ = tokio::time::sleep_until(deadline) => break,
                        result = content_changes.changed() => {
                            if result.is_err() || grant.read().await.is_none() { break; }
                        }
                        result = network_changes.changed() => {
                            if result.is_err() || !grant.scope.is_current() { break; }
                        }
                    }
                }
            };
            tokio::select! {
                _ = &mut server => {}
                _ = invalidation => {
                    stop.send_replace(true);
                    let _ = server.await;
                }
            }
            let mut active = state.0.lock().expect("LAN review state");
            *active = None;
        });
        runtime.register_graceful_host_task(runtime_end.0, task);
        Ok(LanReviewLink { url })
    })
    .await
    .map_err(|_| invalid("LAN sharing startup stopped"))?
}

struct Grant {
    admission: Arc<RuntimeAdmission>,
    node: NodeState,
    source: FavoriteSource,
    preview: String,
    scope: LanIpv4Scope,
    path: String,
    revision: u64,
    deadline: Instant,
    stopping: watch::Receiver<bool>,
}

impl Grant {
    async fn read(self: &Arc<Self>) -> Option<String> {
        if *self.stopping.borrow() || Instant::now() >= self.deadline {
            return None;
        }
        let runtime = timeout(Duration::from_secs(2), self.node.0.clone().read_owned())
            .await
            .ok()?;
        let grant = self.clone();
        tokio::task::spawn_blocking(move || {
            let runtime = runtime.as_ref()?;
            grant.admission.checked_at_lock_revision(runtime, grant.revision, || {
                if !grant.scope.is_current() {
                    return Err(invalid("LAN review interface changed"));
                }
                let (text, _) = runtime.handle().inspect_lan_review_text(&grant.source)?;
                let stopping = grant.stopping.borrow();
                if *stopping || Instant::now() >= grant.deadline || text != grant.preview {
                    return Err(invalid("LAN review ended"));
                }
                Ok(text)
            }).ok()
        }).await.ok()?
    }
}

#[tauri::command]
pub fn owner_revoke_lan_review(
    owner: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<(), CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    app.session().matching(admission.lease(), |_| app.lan_review.stop())
        .map_err(CommandError::Authorization)
}
EOF
