pub(crate) struct LanReview(Arc<Mutex<Option<PendingReview>>>);

struct PendingReview {
    owner: SessionLease,
    stop: watch::Sender<bool>,
}

struct Reservation {
    state: LanReview,
    stop: watch::Sender<bool>,
}

impl Drop for Reservation {
    fn drop(&mut self) {
        self.stop.send_replace(true);
        *self.state.0.lock().expect("LAN review state") = None;
    }
}

impl LanReview {
    fn reserve(&self, owner: SessionLease) -> Result<Reservation, CommandError> {
        let mut active = self.0.lock().expect("LAN review state");
        if active.is_some() {
            return Err(invalid("Stop the existing LAN review first"));
        }
        let (stop, _) = watch::channel(false);
        *active = Some(PendingReview { owner, stop: stop.clone() });
        Ok(Reservation { state: self.clone(), stop })
    }

    pub(crate) fn stop(&self, lease: &SessionLease) {
        if let Some(review) = self.0.lock().expect("LAN review state").as_ref()
            .filter(|review| &review.owner == lease)
        {
            review.stop.send_replace(true);
        }
    }
}

