    "-o", "BatchMode=yes", "-o", "ConnectTimeout=4", "windows10",
    \`powershell.exe -NoProfile -NonInteractive -EncodedCommand \${encoded}\`,
  ], { timeout: 45_000 });
  assert.match(result.stdout, /literal-text-ok/);
}

async function expectClosed(url) {
  await until("listener closed", async () => {
    try { await fetch(url, { signal: AbortSignal.timeout(800) }); return false; }
